#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n;
    if (scanf("%d", n) != 1) return 0;
    int *a = malloc(n * sizeof(int));
    if (a == NULL) return 1;
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);
    for (int i = n - 1; i >= 0; i--) printf("%d%c", a[i], i ? ' ' : '\n');
    free(a);
    return 0;
}

