#include <stdio.h>

void swap(int *x, int *y) {
    int t = *x;
    *x = *y;
    *y = t;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    for (int i = 0; i < n; i++) {
        int a, b;
        scanf("%d %d", &a, b);
        if (a > b) swap(&a, &b);
        printf("%d %d\n", a, b);
    }
    return 0;
}

